const receiptRoundedFont=new FontFace('ReceiptRounded','url(receipt-rounded.woff2)');
const receiptRoundedReady=receiptRoundedFont.load().then(font=>document.fonts.add(font));
function receiptRoundedAmount(ctx,text,right,y){const step=Math.max(...'0123456789'.split('').map(c=>ctx.measureText(c).width));ctx.textAlign='left';let left=right-text.length*step;for(const c of text){ctx.fillText(c,left+(step-ctx.measureText(c).width)/2,y);left+=step;}ctx.textAlign='right';}
/* Customer receipt: display and clipboard share exactly the same PNG. */
const ONLINE_RECEIPT_LOGO='data:image/png;base64,';
let onlineReceiptCurrent=null;
const onlineReceiptMoney=n=>'$'+Number(n||0).toLocaleString('en-US');
function onlineReceiptData(rows,read=getOnlineData){
 const items=[],byName=new Map();let total=0,deposit=0;
 for(const row of rows){const name=String(read(row,['名稱','商品名稱'])||'未填名稱').trim(),amount=numberValue(read(row,['售價','價格']));let item=byName.get(name);if(!item){item={name,qty:0,amount:0};byName.set(name,item);items.push(item)}item.qty++;item.amount+=amount+numberValue(read(row,['運費']));total+=((read===getOnlineData&&isRestockRow(row))?0:amount+numberValue(read(row,['運費'])));deposit+=numberValue(read(row,['訂金']));}
 const now=new Date(),stamp=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(now).replace(/-/g,'/');
 return {items,total,deposit,pages:Math.max(1,Math.ceil(items.length/15)),page:0,stamp,canvases:new Map()};
}
async function onlineReceiptBaseCanvas(state,page){await receiptRoundedReady;const {items,total,deposit,pages,stamp}=state;const c=document.createElement('canvas'),rows=items.slice(page*15,page*15+15),shorten=(15-rows.length)*57,footerCut=page<pages-1?160:0,logicalHeight=1304-shorten-footerCut;c.width=1800;c.height=Math.round(logicalHeight*2400/760);const x=c.getContext('2d');x.scale(2400/760,2400/760);x.fillStyle='#fafafa';x.fillRect(0,0,570,logicalHeight);const img=new Image();img.src=ONLINE_RECEIPT_LOGO;await img.decode();x.drawImage(img,202.5,35,165,54);x.fillStyle='#514237';x.font='20px ReceiptRounded, sans-serif';x.textAlign='center';x.fillText(stamp+'　JIWU寶寶明細',285,123);x.strokeStyle='#aaa';x.setLineDash([5,5]);x.beginPath();x.moveTo(35,225);x.lineTo(535,225);x.stroke();x.font='24px ReceiptRounded, sans-serif';x.textAlign='left';x.fillText('名稱',35,205);x.textAlign='center';x.fillText('數量',407,205);x.textAlign='right';x.fillText('金額',535,205);rows.forEach((r,i)=>{let y=265+i*57;x.fillStyle='#514237';x.font='27px ReceiptRounded, sans-serif';x.textAlign='left';x.font='20px ReceiptRounded, sans-serif';x.fillText(String(page*15+i+1)+'.',35,y);x.font='25px ReceiptRounded, sans-serif';x.fillText(r.name,62,y,290);x.textAlign='center';x.fillText(r.qty,407,y);x.textAlign='right';x.fillText(onlineReceiptMoney(r.amount),535,y);x.strokeStyle='#e6e2dc';x.lineWidth=1;x.setLineDash([1,3]);x.beginPath();x.moveTo(35,y+17);x.lineTo(535,y+17);x.stroke();x.setLineDash([])});let y=1143-shorten;if(page===pages-1){x.strokeStyle='#a8a39b';x.lineWidth=1;x.setLineDash([5,5]);x.beginPath();x.moveTo(35,1103-shorten);x.lineTo(535,1103-shorten);x.stroke();x.setLineDash([]);for(const [label,n] of [[`共計（${items.reduce((n,x)=>n+x.qty,0)}件）`,total],['訂金',deposit],['尾款',total-deposit]]){x.fillStyle='#514237';x.font='28px ReceiptRounded, sans-serif';x.textAlign='left';x.fillText(label,35,y);x.textAlign='right';x.font='28px ReceiptRounded, sans-serif';x.fillStyle=label==='尾款'?'#FF69A0':'#514237';receiptRoundedAmount(x,onlineReceiptMoney(n),535,y);y+=44}}x.font='22px ReceiptRounded, sans-serif';x.textAlign='center';x.fillStyle='#999';if(pages>1)x.fillText(`${page+1} / ${pages}`,285,1269-shorten-footerCut);return c;}
function onlineReceiptLetter(i){let s='';for(i++;i>0;i=Math.floor((i-1)/26))s=String.fromCharCode(65+(i-1)%26)+s;return s;}
async function onlineReceiptGetCanvas(state,page){if(!state.canvases.has(page))state.canvases.set(page,onlineReceiptCanvas(state,page));return state.canvases.get(page);}
async function onlineReceiptPage(step=0){const state=onlineReceiptCurrent;if(!state)return;state.page=(state.page+step+state.pages)%state.pages;const page=state.page;try{const c=await onlineReceiptGetCanvas(state,page);if(onlineReceiptCurrent!==state||page!==state.page)return;const img=document.getElementById('onlineReceiptImage');if(img){img.src=c.toDataURL('image/png');img.alt='JIWU寶寶明細 '+onlineReceiptLetter(page)}const pager=document.getElementById('onlineReceiptPage');if(pager)pager.textContent=state.pages>1?(page+1)+' / '+state.pages:'';}catch(e){const msg=document.getElementById('onlineReceiptStatus');if(msg)msg.textContent=jiwuErrorText(e,'system');}}
async function onlineReceiptCopy(page){const state=onlineReceiptCurrent;if(!state)return;const message=document.getElementById('onlineReceiptStatus');try{const canvas=await onlineReceiptGetCanvas(state,page),blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('圖片產生失敗');await navigator.clipboard.write([new ClipboardItem({'image/png':blob})]);if(message?.isConnected)message.textContent='已複製明細'+onlineReceiptLetter(page);}catch(e){if(message?.isConnected)message.textContent=jiwuErrorText(e,'system');}}
function showSelectedOnlineDetails(){const ids=new Set([...onlineQueryAll('.shipCheck:checked')].map(input=>Number(input.value))),rows=onlineRows.filter(row=>ids.has(Number(row.row)));if(!rows.length){alert('請先勾選要查看的商品');return;}showOnlineReceipt(rows);}
function showOnlineReceipt(rows,read=getOnlineData){onlineReceiptCurrent=onlineReceiptData(rows,read);const state=onlineReceiptCurrent;closeDialog();document.body.insertAdjacentHTML('beforeend',`<div id="appDialog" class="dialogOverlay" onclick="if(event.target===this)closeDialog()"><style>@media(min-width:768px){#appDialog .onlineReceiptDialog{zoom:1!important;width:480px!important;max-width:calc(100vw - 48px)!important;padding:20px!important;max-height:90dvh!important}#appDialog #onlineReceiptImage{width:100%!important}}</style><div class="dialogCard onlineReceiptDialog" role="dialog" aria-modal="true" aria-label="JIWU寶寶明細" style="zoom:1.3043478261;width:253px;max-width:calc(100vw - 16px);padding:14px;background:#f3f1ed;border-radius:20px;max-height:94dvh;overflow:auto"><img id="onlineReceiptImage" alt="明細產生中" style="display:block;width:225px;max-width:100%;height:auto;margin:auto"><div style="display:flex;align-items:center;justify-content:space-between;gap:6px;margin-top:10px;font-size:11px"><div style="display:${state.pages>1?'flex':'none'};align-items:center;gap:6px"><button class="btn light" style="padding:7px 9px" aria-label="上一頁" onclick="onlineReceiptPage(-1)">‹</button><span id="onlineReceiptPage">${state.pages>1?'1 / '+state.pages:''}</span><button class="btn light" style="padding:7px 9px" aria-label="下一頁" onclick="onlineReceiptPage(1)">›</button></div><div style="display:flex;gap:5px;max-width:190px;overflow-x:auto">${Array.from({length:state.pages},(_,i)=>`<button class="btn" style="padding:8px 10px;white-space:nowrap" onclick="onlineReceiptCopy(${i})">明細${onlineReceiptLetter(i)}</button>`).join('')}</div></div><div id="onlineReceiptStatus" role="status" style="min-height:14px;text-align:right;margin-top:4px;font-size:11px;color:#786b5d"></div></div></div>`);state.displayWidth=document.getElementById('onlineReceiptImage').getBoundingClientRect().width;onlineReceiptPage();}

function showShipDetails(button){
 const card=button.closest(".shipOrderCard");
 if(!card||!shipDataCache)return;
 const ids=new Set(card.dataset.rows.split(",").map(Number));
 const rows=shipDataCache.rows.filter(row=>ids.has(Number(row.row))).map(row=>({data:{"名稱":getShipData(row,["名稱","商品名稱"]),"售價":getShipData(row,["售價","價格"]),"訂金":getShipData(row,["訂金"]),"運費":getShipData(row,["運費"])}}));
 if(rows.length)showOnlineReceipt(rows,(row,names)=>row.data[names.find(name=>Object.hasOwn(row.data,name))]??"");
}

const receiptThanksFont=new FontFace('ReceiptThanks','url(data:font/ttf;base64,)',{weight:'800'});
const receiptThanksReady=receiptThanksFont.load().then(font=>document.fonts.add(font));
const RECEIPT_FOOTER_ART='data:image/png;base64,';
async function onlineReceiptCanvas(state,page){
 const original=await onlineReceiptBaseCanvas(state,page);
 if(page!==state.pages-1)return original;
 await receiptThanksReady;
 const scale=2400/760,perPixel=570/(state.displayWidth||480);
 const rows=state.items.slice(page*15,page*15+15),tailY=1231-(15-rows.length)*57;
 const probe=document.createElement('canvas').getContext('2d');
 probe.font='28px ReceiptRounded, sans-serif';
 const tailBottom=tailY+Math.max(probe.measureText('尾款').actualBoundingBoxDescent,probe.measureText(onlineReceiptMoney(state.total-state.deposit)).actualBoundingBoxDescent);
 probe.font='800 25px ReceiptThanks';
 const metrics=probe.measureText('THANKS!'),thanksY=tailBottom+90*perPixel+metrics.actualBoundingBoxAscent;
 const art=new Image();art.src=RECEIPT_FOOTER_ART;await art.decode();
 const artWidth=550,artHeight=artWidth*art.height/art.width,artY=thanksY+metrics.actualBoundingBoxDescent+20*perPixel;
 const c=document.createElement('canvas');c.width=original.width;c.height=Math.ceil((artY+artHeight+20*perPixel)*scale);
 const x=c.getContext('2d');x.fillStyle='#fafafa';x.fillRect(0,0,c.width,c.height);
 const cut=Math.ceil((tailBottom+1)*scale);x.drawImage(original,0,0,original.width,cut,0,0,original.width,cut);
 x.scale(scale,scale);x.fillStyle='#514237';x.textAlign='center';x.font='800 25px ReceiptThanks';x.fillText('THANKS!',285,thanksY);
 x.drawImage(art,10,artY,artWidth,artHeight);
 return c;
}
